def cryptage(s):
    nb=1
    ch=''
    for i in range(len(s)):
        if s[i]!=' ':
            
            r=(ord(s[i])+nb)
            if 'A'<=s[i]<='Z':
                p=ord('Z')
            else:
                p=ord('z')
                
            while(r>p):
                r=r - 26
            
                    
                    
            ch=ch+chr(r)
        else:
            ch=ch+' '
            nb=nb+1
    return ch
    
    
            
            

