from PyQt5.uic import loadUi
from PyQt5.QtWidgets import QApplication
from numpy import *

T1 = array([str] * 100)
T2 = array([str] * 100)


def verif(ch1, ch2):
    if ch1 != '' and ch2 != '':
        if nombre_mot(ch1) == nombre_mot(ch2):
            return True
        else:
            return False
    else:
        return False


def verif2(ch):
    ok = ch[0] != ' ' and ch[len(ch) - 1] == '.' and len(ch) <= 200
    i = -1
    while i < len(ch) - 2 and ok:
        i += 1
        ok = "A" <= ch[i] <= "Z" or ch[i] == " "
    return ok


def nombre_mot(ch):
    p = 0
    for i in range(len(ch) - 1):
        if "A" <= ch[i].upper() <= "Z" and ch[i + 1] == " ":
            p += 1
    return p


def superflus(ch):
    while ch[0] == ' ':
        ch = ch[1:]
    while ch[len(ch) - 1] == ' ':
        ch = ch[:len(ch) - 2]
    while ch.find("  ") != -1:
        x = ch.find("  ")
        ch = ch[:x] + ch[x + 1:]

    return ch


def Remplir(T, ch, n):
    i = 0
    S = ch + ' '
    while S != '' and i < n:
        x = S.find(" ")
        T[i] = S[:x]
        S = S[x + 1:]
        i += 1


def commun(t1, t2, n):
    p = 0
    for i in range(n):
        for j in range(n):
            if t1[i] == t2[j]:
                p += 1
    return p


def Traitement(ch1, ch2):
    if verif(ch1, ch2) and verif2(ch1) and verif2(ch2):
        ph1 = superflus(ch1)
        ph2 = superflus(ch2)
        Remplir(T1, ph1, nombre_mot(ph1))
        Remplir(T2, ph2, nombre_mot(ph1))
        n = commun(T1, T2, nombre_mot(ph1))
        if n > nombre_mot(ph1) / 2:
            p.t1.setText('Le texte est plagiat')
        else:
            p.t1.setText('Le texte n\'est pas plagiat')
    else:
        p.t1.setText('INPUT ERROR')


