from numpy import *

Matricule = array([str] * 100)
Score = array([int] * 100)


def Saisie():
    b = False
    while not b:
        n = int(input("Donner le nombre des participants: "))
        b = 5 <= n <= 100
    return n


def RemplirMarticule(N):
    for i in range(N):
        b = False
        while not b:
            Matricule[i] = str(input("Matricule[" + str(i) + "]= "))
            b = Matricule[i].isnumeric() and len(Matricule[i]) == 8


def RemplirScore(N):
    for i in range(N):
        b = False
        while not b:
            Score[i] = int(input("Score[" + str(i) + "]= "))
            b = 20 <= Score[i] <= 120


def Resultat(Matricule, Score, N):
    for i in range(N - 1):
        idmax = maxi(Score, i + 1, N)
        if idmax != i:
            temp1 = Score[i]
            Score[i] = Score[idmax]
            Score[idmax] = temp1
            temp2 = Matricule[i]
            Matricule[i] = Matricule[idmax]
            Matricule[idmax] = temp2


def maxi(t, a, b):
    p = a
    for i in range(a, b):
        if t[p] < t[i]:
            p = i
    return p


def Afficher(Matricule, N):
    p = int(round(N / 4, 0))
    for i in range(p + 1):
        print("liste des admis : \t ", Matricule[i])


#####################PP########################

N = Saisie()
RemplirMarticule(N)
RemplirScore(N)
Resultat(Matricule, Score, N)
Afficher(Matricule, N)


