#Trier un tableau dans l'ordre croissant par la méthode de tri sélection

from numpy import *

t=array([int]*25)

def Saisie():
    b = False
    while not(b):
        x=int(input("Donner le nombre des cases: "))
        b = 0<=x<=25
    return x

def Remplir(n):
    for i in range (n):
        t[i]=int(input("t["+str(i)+"]= "))

def tri(n,t):
    for i in range (n-1) :
        idmin = mini(t,i,n)
        if idmin != i :
            temp = t[i]
            t[i] = t[idmin]
            t[idmin] = temp

def mini(t,a,b):
    p = a
    for i in range(a+1,b):
        if t[p] > t[i] :
            p = i
    return p

def Afficher(t,n):
    for i in range(n):
        print(t[i])

###############PP###################
n=Saisie()
Remplir(n)
tri(n,t)
Afficher(t,n)





