    return n


def premier(x):
    b = x > 1
    d = 2
    while b and (d <= x // 2):
        b = x % d != 0
        d += 1
    return b


def puissance(x, y):
    R = 1
    for i in range(y):
        R *= x
    return R


def facteurs(n, t):
    ch = ""
    i = 2
    j = 0
    while abs(n) != 1:
        if premier(i):
            if (n % i) == 0:
                ch += str((i)) + "/"
                t[j] = i
                j += 1
                n //= i
            else:
                i += 1
        else:
            i += 1
    return ch, i, j


def compter(x, t, n):  
    s = 0
    for i in range(n):
        if t[i] == x:
            s += 1
    return s


def PGCD(a, b, a1, b1, a2, b2):
    if a1 >= b1:
        m = a1
    else:
        m = b1
    d = 1
    for i in range(2, m + 1):
        if compter(i, ta, a2) <= compter(i, tb, b2):
            d *= puissance(i, compter(i, ta, a2))
        else:
            d *= puissance(i, compter(i, tb, b2))
    return d


