    b = False
    while not (b):
        ch = str(input('< '))
        b = verif(ch)
    return ch


def verif(ch):
    ok = True
    i = -1
    while i < len(ch) - 1 and ok:
        i += 1
        ok = "A" <= ch[i] <= "Z"
    return ok


def occurence(c, ch):
    p = 0
    for i in range(len(ch)):
        if ch[i] == c:
            p += 1
    return p


def Crypter(ch):
    R = ''
    for i in range(len(ch)):
        n = occurence(ch[i], ch)
        if n % 2 == 1:
            k = 2 * n
        else:
            k = n // 2
        if "A" <= chr(ord(ch[i]) + k) <= "Z":
            R += chr(ord(ch[i]) + k)
        else:
            R += chr(ord(ch[i]) + k - 26)
    return R


