from numpy import *

t = array([int] * 20)


def Saisie():
    b = False
    while not (b):
        n = int(input("Donner le nombre des cases: "))
        b = 5 <= n <= 20
    return n


def Remplir(n):
    for i in range(n):
        t[i] = int(input("t[" + str(i) + "] = "))


def suppression(t, n):
    i = 0
    while i < n:
        if t[i] == 5:  #par exemple en veut effacer les cases'5'
            n = efface(t, i, n)
        i += 1
    return n


def efface(t, i, n):
    for j in range(i, n - 1):
        t[j] = t[j + 1]
    n -= 1
    return n


def Afficher(t, n):
    for i in range(n):
        print(t[i], end=' ')


