#Trier un tableau dans l'ordre croissant par la méthode de tri à bulles

from numpy import *

t = array ( [int] * 20 )

def Saisie():
    b = False
    while not(b) :
        n=int(input("Donner le nombre des cases: "))
        b = 5 <= n <= 20
    return n

def Remplir(n):
    for i in range (n):
        t[i]=int(input("t["+str(i)+"] = "))

def tri(t,n):
    echange = False 
    while n != 1 or not echange :
        for i in range(n-1):
            if t[i] > t[i+1]:
                temp = t[i]
                t[i] = t[i+1]
                t[i+1] = temp
                echange = True
        n -= 1

def Afficher(t,n):
    for i in range (n):
        print(t[i],end="/")

####################PP####################

n = Saisie()
Remplir(n)
tri(t,n)
Afficher(t,n)

